module spi_controller #(parameter CLK_FREQ = 50_000_000, parameter DATA_LENGTH = 8) (  
    input wire clk,  
    input wire rst_n,  
    input wire start,  
    input wire [DATA_LENGTH-1:0] data_in,  
    output reg [DATA_LENGTH-1:0] data_out,  
    output reg active,  
    output reg interrupt,  
    output reg MOSI,  
    input wire MISO,  
    output reg SCLK,  
    output reg SS  
);  
    reg [3:0] state;  
    reg [3:0] count;  
    reg [DATA_LENGTH-1:0] shift_reg;  

    // State definitions  
    localparam IDLE = 4'b0000,  
               SEND = 4'b0001,  
               RECEIVE = 4'b0010,  
               DONE = 4'b0011;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            state <= IDLE;  
            active <= 0;  
            SCLK <= 0;  
            SS <= 1;  
            interrupt <= 0;  
            count <= 0;  
            data_out <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        SS <= 0;  
                        shift_reg <= data_in;  
                        count <= 0;  
                        state <= SEND;  
                        active <= 1;  
                    end  
                end  
                SEND: begin  
                    if (count < DATA_LENGTH) begin  
                        MOSI <= shift_reg[DATA_LENGTH-1];  
                        shift_reg <= {shift_reg[DATA_LENGTH-2:0], 1'b0};  
                        SCLK <= 1;  
                        count <= count + 1;  
                        state <= RECEIVE;  
                    end else begin  
                        state <= DONE;  
                    end  
                end  
                RECEIVE: begin  
                    SCLK <= 0;  
                    if (count < DATA_LENGTH) begin  
                        data_out <= {data_out[DATA_LENGTH-2:0], MISO};  
                        count <= count + 1;  
                        state <= SEND;  
                    end else begin  
                        state <= DONE;  
                    end  
                end  
                DONE: begin  
                    SS <= 1;  
                    active <= 0;  
                    interrupt <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

