module watchdog_timer (
    input wire clk,
    input wire reset,
    output reg timeout,
    output reg [3:0] count
);
    parameter LIMIT = 10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
            timeout <= 1'b0;
        end else if (count < LIMIT) begin
            count <= count + 1;
            timeout <= 1'b0;
        end else begin
            timeout <= 1'b1;
        end
    end
endmodule

