module watchdog_timer(  
    input clk,  
    input rst,  
    input kick,  
    output reg timeout  
);  
    parameter TIMEOUT_VALUE = 10;  
    reg [3:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            timeout <= 0;  
        end else begin  
            if (kick) begin  
                counter <= 0;  
                timeout <= 0;  
            end else begin  
                if (counter < TIMEOUT_VALUE)  
                    counter <= counter + 1;  
                else  
                    timeout <= 1;  
            end  
        end  
    end  
endmodule

