module temperature_shutdown (
    input wire clk,
    input wire reset,
    input wire [7:0] temp,
    output reg shutdown
);
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shutdown <= 0;
        end else if (temp > 8'd75) begin
            shutdown <= 1;
        end else begin
            shutdown <= 0;
        end
    end
