module floyd_warshall(input [63:0] dist_in, output reg [63:0] dist_out);  
    integer i, j, k;  
    reg [3:0] dist [0:3][0:3];  

    initial begin  
        // Convert input to 2D array  
        for (i = 0; i < 4; i = i + 1)  
            for (j = 0; j < 4; j = j + 1)  
                dist[i][j] = dist_in[ (i * 4 + j) * 4 +: 4 ];  
    end  

    always @* begin  
        // Floyd-Warshall algorithm  
        for (k = 0; k < 4; k = k + 1) begin  
            for (i = 0; i < 4; i = i + 1) begin  
                for (j = 0; j < 4; j = j + 1) begin  
                    if (dist[i][j] > dist[i][k] + dist[k][j]) begin  
                        dist[i][j] = dist[i][k] + dist[k][j];  
                    end  
                end  
            end  
        end  

        // Convert 2D array back to output  
        for (i = 0; i < 4; i = i + 1)  
            for (j = 0; j < 4; j = j + 1)  
                dist_out[ (i * 4 + j) * 4 +: 4 ] = dist[i][j];  
    end  
endmodule

module eeprom_cell(  
    input wire clk,  
    input wire write_enable,  
    input wire read_enable,  
    input wire data_in,  
    output reg data_out  
);  
    always @(posedge clk) begin  
        if (write_enable)  
            data_out <= data_in;  
    end  
endmodule

