module PLL (
    input wire clk_in,
    input wire reset,
    input wire [3:0] control_voltage,
    output reg clk_out
);
    reg [3:0] frequency_divider;
    reg [3:0] count;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            count <= 0;
            clk_out <= 0;
            frequency_divider <= 4'b0001; // Default divider
        end else begin
            count <= count + 1;
            if (count >= frequency_divider) begin
                clk_out <= ~clk_out;
                count <= 0;
            end
        end
    end

    always @(posedge clk_in) begin
        frequency_divider <= control_voltage + 1; // Update divider based on control voltage
    end
endmodule

