module deserializer (
    input wire clk,
    input wire rst,
    input wire serialized_input,
    output reg [31:0] parallel_output
);
    reg [4:0] count; // to count number of bits received

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            parallel_output <= 32'b0;
        end else begin
            if (count < 32) begin
                parallel_output <= {parallel_output[30:0], serialized_input};
                count <= count + 1;
            end
        end
    end
endmodule

