module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg busy
);

    parameter BAUD_RATE_DIV = 104; // Assume 9600 baud rate with 100 MHz clock
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;

    reg [1:0] state;
    reg [3:0] bit_count;
    reg [7:0] data_reg;
    reg [6:0] baud_counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            tx <= 1'b1; // Idle state for UART is high
            busy <= 1'b0;
            bit_count <= 4'b0;
            baud_counter <= 7'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (send && !busy) begin
                        data_reg <= data_in;
                        state <= START;
                        busy <= 1'b1;
                        tx <= 1'b0; // Start bit
                        baud_counter <= 7'b0;
                    end
                end

                START: begin
                    if (baud_counter == BAUD_RATE_DIV) begin
                        baud_counter <= 7'b0;
                        state <= DATA;
                        bit_count <= 4'b0;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end

                DATA: begin
                    if (baud_counter == BAUD_RATE_DIV) begin
                        baud_counter <= 7'b0;
                        tx <= data_reg[bit_count]; // Send data bit
                        bit_count <= bit_count + 1;

                        if (bit_count == 4'b0111) begin // Last data bit sent
                            state <= STOP;
                        end
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end

                STOP: begin
                    if (baud_counter == BAUD_RATE_DIV) begin
                        baud_counter <= 7'b0;
                        tx <= 1'b1; // Stop bit
                        busy <= 1'b0;
                        state <= IDLE;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
            endcase
        end
    end
endmodule

