module watchdog_timer(  
    input clk,  
    input rst_n,  
    input trigger,  
    output reg reset  
);  
    parameter TIMEOUT = 10; // Define the timeout period  
    reg [3:0] counter; // 4-bit counter to count clock cycles  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            counter <= 0;  
            reset <= 0;  
        end else if (trigger) begin  
            counter <= 0;  
            reset <= 0;  
        end else if (counter >= TIMEOUT) begin  
            reset <= 1;  
        end else begin  
            counter <= counter + 1;  
        end  
    end  
endmodule

module pipo_shift_register(  
    input wire clk,  
    input wire reset,  
    input wire load,  
    input wire shift,  
    input wire output_enable,  
    input wire [4:0] data_in,  
    output reg [4:0] data_out  
);  

    reg [4:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 5'b0;  
            data_out <= 5'b0;  
        end else begin  
            if (load) begin  
                shift_reg <= data_in;  
            end else if (shift) begin  
                shift_reg <= {shift_reg[3:0], 1'b0};  
            end  
        end  
    end  

    always @(*) begin  
        if (output_enable)  
            data_out = shift_reg;  
        else  
            data_out = 5'bz;  
    end  
endmodule

module ARQ_System(
    input wire clk,
    input wire rst,
    input wire [3:0] data_in,
    input wire control_signal,
    output reg [3:0] data_out,
    output reg retransmit
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        data_out <= 4'b0000;
        retransmit <= 1'b0;
    end else begin
        if (control_signal) begin
            data_out <= data_in;
            retransmit <= 1'b0;
        end else begin
            retransmit <= 1'b1;
        end
    end
end

endmodule

