module crc_generator(  
    input clk,  
    input rst,  
    input [7:0] data_in,  
    input data_valid,  
    output reg [7:0] crc_out  
);  
    reg [7:0] crc;  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            crc <= 8'b0;  
            crc_out <= 8'b0;  
        end else if (data_valid) begin  
            crc = crc ^ data_in;  
            for (i = 0; i < 8; i = i + 1) begin  
                if (crc[7]) begin  
                    crc = (crc << 1) ^ 8'b100000111;  
                end else begin  
                    crc = crc << 1;  
                end  
            end  
            crc_out <= crc;  
        end  
    end  
endmodule

