module sd_card_controller(
    input wire clk,
    input wire reset,
    input wire [1:0] cmd, // 00: no operation, 01: write, 10: read
    input wire [7:0] data_in,
    output reg [7:0] data_out,
    output reg ready
);

    reg [7:0] memory [0:255]; // Simple memory to simulate SD card
    reg [7:0] address;
    reg writing;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ready <= 0;
            writing <= 0;
            address <= 0;
            data_out <= 8'b0;
        end else begin
            case (cmd)
                2'b01: begin // Write operation
                    memory[address] <= data_in;
                    writing <= 1;
                    ready <= 1;
                end
                2'b10: begin // Read operation
                    data_out <= memory[address];
                    writing <= 0;
                    ready <= 1;
                end
                default: ready <= 0; // No operation
            endcase
            if (ready) address <= address + 1; // Increment address after operation
        end
    end
endmodule

