module spi_master(  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    input wire [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg mosi,  
    output reg miso,  
    output reg sclk,  
    output reg ss  
);  
    reg [2:0] state;  
    reg [2:0] count;  

    localparam IDLE = 3'b000,  
               SEND = 3'b001,  
               RECEIVE = 3'b010,  
               DONE = 3'b011;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            count <= 0;  
            mosi <= 0;  
            sclk <= 0;  
            ss <= 1;  
            data_out <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (enable) begin  
                        ss <= 0;  
                        count <= 0;  
                        state <= SEND;  
                    end  
                end  
                SEND: begin  
                    mosi <= data_in[7 - count];  
                    sclk <= 1;  
                    count <= count + 1;  
                    if (count == 7) state <= RECEIVE;  
                end  
                RECEIVE: begin  
                    data_out[7 - count] <= miso;  
                    sclk <= 0;  
                    count <= count + 1;  
                    if (count == 7) state <= DONE;  
                end  
                DONE: begin  
                    ss <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

