module SRT_Divider (
    input clk,
    input rst,
    input start,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);

    reg [3:0] state;
    reg [15:0] A, Q, M, Q_temp;
    reg [4:0] count;

    parameter IDLE = 0, LOAD = 1, DIVIDE = 2, SHIFT = 3, DONE = 4;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            A <= 0;
            Q <= 0;
            M <= 0;
            quotient <= 0;
            remainder <= 0;
            count <= 0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        A <= dividend;
                        M <= divisor;
                        Q <= 0;
                        count <= 16;
                        state <= LOAD;
                    end
                end

                LOAD: begin
                    Q_temp <= Q;
                    state <= DIVIDE;
                end

                DIVIDE: begin
                    if (M <= A) begin
                        A <= A - M;
                        Q_temp <= Q_temp + 1;
                    end
                    if (count > 0) begin
                        count <= count - 1;
                        state <= SHIFT;
                    end else begin
                        state <= DONE;
                    end
                end

                SHIFT: begin
                    A <= A << 1;
                    A[0] <= Q_temp[15];
                    Q <= Q_temp;
                    state <= DIVIDE;
                end

                DONE: begin
                    quotient <= Q;
                    remainder <= A;
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

