module fractional_n_pll (
    input wire clk_ref,
    input wire [15:0] fractional,
    input wire reset,
    output reg clk_out
);
    reg [15:0] counter;
    reg [31:0] phase_accumulator;

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            counter <= 0;
            phase_accumulator <= 0;
            clk_out <= 0;
        end else begin
            phase_accumulator <= phase_accumulator + fractional;
            if (phase_accumulator[31:16] >= 16'hFFFF) begin
                clk_out <= ~clk_out;
                phase_accumulator[31:16] <= phase_accumulator[31:16] - 16'hFFFF;
            end
        end
    end
endmodule

