module serializer_16bit(  
    input clk,  
    input reset,  
    input [15:0] data_in,  
    output reg serial_out  
);  
    reg [3:0] bit_counter;  
    reg [15:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 16'b0;  
            bit_counter <= 4'b0;  
            serial_out <= 1'b0;  
        end else begin  
            if (bit_counter < 16) begin  
                serial_out <= shift_reg[15];  
                shift_reg <= {shift_reg[14:0], 1'b0};  
                bit_counter <= bit_counter + 1;  
            end else begin  
                serial_out <= 1'b0; // Hold serial_out low after serialization  
            end  
        end  
    end  

    always @(posedge clk) begin  
        if (bit_counter == 0) begin  
            shift_reg <= data_in;  
        end  
    end  
endmodule

