module divide_by_8 (
    input wire clk,
    input wire reset,
    output reg out
);
    reg [2:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 3'b000;
            out <= 0;
        end else begin
            if (counter == 3'b111) begin
                out <= 1;
                counter <= 3'b000;
            end else begin
                out <= 0;
                counter <= counter + 1;
            end
        end
    end
endmodule

